CREATE TABLE IF NOT EXISTS transform_runs(transform_run_id TEXT PRIMARY KEY,caller_identity TEXT NOT NULL,idempotency_key TEXT NOT NULL,execution_mode TEXT NOT NULL,contract_digest TEXT NOT NULL,plan_digest TEXT NOT NULL,status TEXT NOT NULL,accepted_at TEXT NOT NULL,heartbeat_at TEXT NOT NULL,UNIQUE(caller_identity,idempotency_key));
CREATE TABLE IF NOT EXISTS batch_executions(batch_execution_id TEXT PRIMARY KEY,transform_run_id TEXT NOT NULL,caller_identity TEXT NOT NULL,idempotency_key TEXT NOT NULL,batch_id TEXT NOT NULL,authority TEXT NOT NULL,model_fingerprint TEXT NOT NULL,status TEXT NOT NULL,accepted_at TEXT NOT NULL,started_at TEXT,finished_at TEXT,attempt INTEGER NOT NULL,test_status TEXT,failure_class TEXT,heartbeat_at TEXT NOT NULL,cancel_requested INTEGER NOT NULL DEFAULT 0,lease_owner TEXT,lease_token TEXT,lease_expires_at TEXT,cancel_requested_at TEXT,nessie_branch TEXT,nessie_base_ref TEXT,nessie_base_hash TEXT,nessie_source_hash TEXT,publication_status TEXT,UNIQUE(caller_identity,idempotency_key));
CREATE TABLE IF NOT EXISTS batch_attempts(batch_attempt_id INTEGER PRIMARY KEY AUTOINCREMENT,batch_execution_id TEXT NOT NULL,attempt INTEGER NOT NULL,status TEXT NOT NULL,heartbeat_at TEXT NOT NULL,UNIQUE(batch_execution_id,attempt));
CREATE TABLE IF NOT EXISTS execution_events(event_id TEXT PRIMARY KEY,transform_run_id TEXT NOT NULL,batch_execution_id TEXT,event_type TEXT NOT NULL,event_at TEXT NOT NULL,metadata_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS execution_locks(lock_name TEXT PRIMARY KEY,transform_run_id TEXT NOT NULL,acquired_at TEXT NOT NULL,heartbeat_at TEXT NOT NULL);
